INSERT INTO feature VALUES('native-primitives','types','Native integers, booleans and strings',NULL,'implemented','ordinary',NULL,'Arbitrary-precision integers, booleans and strings with a table of native primitives and a prelude; the normaliser runs one kind of them, the literal identity tests `int.eq`, `eq`, `ne` and `string.eq`, which answer on two literals as the kernel computes them again by its own comparison, its audit naming each a kernel primitive. It holds every other call as a neutral on its operation, so two such calls convert exactly when their operations and arguments do.','core-sequent core-nbe core-checker kernel-core kernel-term core-term','corpus/model/identity/here-congruence.gandr corpus/model/basics/booleans.gandr corpus/pathological/basics/booleans.gandr corpus/model/basics/literal-identity.gandr','corpus/model/identity/here-congruence.gandr',NULL);
